for(const large of [false,true])test('merged Lark '+(large?'original-file':'snapshot')+' socket sync ignores counters across restart and retains scoped real corrections',async t=>{
 let revision=1;const bodies=new Map<string,string>(),body=(large?'Generated Markdown row\n'.repeat(6000):'Generated Markdown body');
 const lark:NonNullable<ConnectorTransports['lark']>=scope=>async(command,options)=>{options?.signal?.throwIfAborted();switch(command.kind){case 'version':return 'lark-cli 1.0.98';case 'status':return JSON.stringify({appId:'cli_same',identities:{user:{available:true,openId:'same-open-id',scope:'docx:document:readonly wiki:wiki:readonly search:docs:read space:document:retrieve'}}});case 'login':return JSON.stringify({verification_url:'https://accounts.feishu.cn/generated',device_code:'generated-'+scope.userId,expires_in:600});case 'complete':return '{}';case 'document':return JSON.stringify({data:{document:{document_id:'SameDocument123',revision_id:revision,title:'Generated document',content:bodies.get(scope.userId)??body+' PRIVATE-'+scope.userId}}});default:throw Error('Unexpected generated Lark I/O '+command.kind);}};
 const f=await fixture(t,{extra:{lark}});await f.install('lark');for(const token of [f.alice.token,f.bob.token]){await f.configure(token,'lark');await f.action(token,'enable');await f.operation(token,'login',{});await f.operation(token,'select',{documents:['DocumentFixture123'],calendarIds:[],pastDays:30,futureDays:90,timeZone:'UTC',autoSync:false});await socketConnectorSync(f,token);}
 const heads=async(token:string)=>(await f.request(token,'/api/source-items')).json().items,first=(await heads(f.alice.token))[0],bFirst=(await heads(f.bob.token))[0],source=(await f.request(f.alice.token,'/api/sources')).json().items[0];assert.equal(first.externalId,bFirst.externalId);
 await f.restart();revision++;assert.equal((await socketConnectorSync(f,f.alice.token)).result.job.result.imported,0);assert.equal((await heads(f.alice.token))[0].captureId,first.captureId);
 bodies.set(f.a.userId,body+' PRIVATE-'+f.a.userId+'\nGenerated correction');revision++;assert.equal((await socketConnectorSync(f,f.alice.token)).result.job.result.imported,1);const changed=(await heads(f.alice.token))[0];assert.notEqual(changed.captureId,first.captureId);assert.notEqual(changed.revision,first.revision);assert.equal((await socketConnectorSync(f,f.alice.token)).result.job.result.imported,0);
 const originals=(await f.request(f.alice.token,'/api/ingress/sources/'+source.id+'/originals')).json().items,ref=originals.find((value:any)=>value.captureId===changed.captureId).ref;assert.ok((await connectorOriginalBytes(f,f.alice.token,ref)).toString().includes('Generated correction'));
 bodies.delete(f.a.userId);revision++;assert.equal((await socketConnectorSync(f,f.alice.token)).result.job.result.imported,1);assert.notEqual((await heads(f.alice.token))[0].captureId,first.captureId);assert.equal((await f.request(f.alice.token,'/api/sources/'+source.id+'/history?externalId=SameDocument123')).json().items.length,3);assert.deepEqual((await heads(f.bob.token))[0],bFirst);assert.equal((await socketConnectorSync(f,f.bob.token)).result.job.result.imported,0);
});
